class PsRadio extends HTMLElement{constructor(){super(),this.attachShadow({mode:"open"});const e=document.createElement("template");e.innerHTML=`\n            <style>\n                :host {\n                    display: inline-flex;\n                    align-items: center;\n                    height: 23px;\n                }\n\n                sp-radio {\n                    display: inline-flex;\n                    align-items: center;\n                    margin-right: 5px;\n                }\n\n                label {\n                    color: var(--uxp-host-text-color); \n                    font-family: 'Arial', sans-serif; \n                    font-size: 0.9em; \n                    transform: translate(-5px, 2px);\n                }\n\n                :host([disabled]) {\n                    pointer-events: none; /* Previne clicks no estado disabled */\n                }\n\n                :host([disabled]) label {\n                    color: #8f8c8c;\n                }\n            </style>\n            <sp-radio size="s" class="radio-element"><label>${this.innerText||"Opção"}</label></sp-radio>\n            \n        `,this.shadowRoot.appendChild(e.content.cloneNode(!0)),this.radio=this.shadowRoot.querySelector("sp-radio"),this.label=this.shadowRoot.querySelector("label"),this.hasAttribute("data")&&this.radio.setAttribute("data",this.getAttribute("data")),this.radio.addEventListener("click",(e=>{if(this.disabled)return e.stopPropagation(),void console.log("Elemento está desabilitado.");this.checked=!this.checked,this.dispatchEvent(new CustomEvent("change",{detail:{checked:this.checked}}))}))}static get observedAttributes(){return["checked","disabled","data"]}attributeChangedCallback(e,t,i){"checked"===e?null!==i?this.radio.setAttribute("checked",""):this.radio.removeAttribute("checked"):"disabled"===e?null!==i?this.radio.setAttribute("disabled",""):this.radio.removeAttribute("disabled"):"data"===e&&this.radio.setAttribute("data",i)}get checked(){return this.hasAttribute("checked")}set checked(e){e?this.setAttribute("checked",""):this.removeAttribute("checked")}get disabled(){return this.hasAttribute("disabled")}set disabled(e){e?this.setAttribute("disabled",""):this.removeAttribute("disabled")}}customElements.define("ps-radio",PsRadio);